import{_ as E,C as l,o as d,c as u,a2 as e,b as i,w as a,a as n,E as o,a3 as s}from"./chunks/framework.BYgiQ6KE.js";const f=JSON.parse('{"title":"18 · 迁移与架构治理","description":"把「能跑」的 Angular 应用迁移到 standalone、signal 与 zoneless，并用边界与门禁把架构约束固化下来。","frontmatter":{"title":"18 · 迁移与架构治理","description":"把「能跑」的 Angular 应用迁移到 standalone、signal 与 zoneless，并用边界与门禁把架构约束固化下来。"},"headers":[],"relativePath":"guide/part7/18-migration-governance.md","filePath":"guide/part7/18-migration-governance.md","lastUpdated":1793863170000}'),h={name:"guide/part7/18-migration-governance.md"};function g(_,t,p,A,m,B){const r=l("Mermaid"),c=l("Playground");return d(),u("div",null,[t[2]||(t[2]=e('<h1 id="_18-·-迁移与架构治理" tabindex="-1">18 · 迁移与架构治理 <a class="header-anchor" href="#_18-·-迁移与架构治理" aria-label="Permalink to &quot;18 · 迁移与架构治理&quot;">​</a></h1><blockquote><p>所属：第七篇 · 精通专题　配套示例：<code>architecture</code></p></blockquote><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><ul><li>制定 AngularJS → Angular、NgModule → standalone 的分阶段迁移路线</li><li>判断哪些代码可以机械迁移，哪些必须重写并补测试</li><li>用依赖方向、边界规则与所有权约定约束大型代码库</li><li>把版本升级、弃用清理与质量门禁变成可持续的流程</li><li>说明迁移中的风险点：双框架运行、路由冲突、状态重复、构建体积回退</li></ul><h2 id="_1-迁移不是一次重写" tabindex="-1">1. 迁移不是一次重写 <a class="header-anchor" href="#_1-迁移不是一次重写" aria-label="Permalink to &quot;1. 迁移不是一次重写&quot;">​</a></h2><p>大型应用的迁移失败，通常不是因为技术难，而是因为「一次性重写」：范围失控、无法回归、业务 等不起。可行路线是把迁移拆成可独立验证的阶段，每一阶段都能上线、能回滚。</p>',6)),(d(),i(s,null,{default:a(()=>[o(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%E7%8E%B0%E7%8A%B6%E7%9B%98%E7%82%B9%5D%20--%3E%20B%5B%E5%BB%BA%E7%AB%8B%E6%B5%8B%E8%AF%95%E4%B8%8E%E9%97%A8%E7%A6%81%5D%0A%20%20B%20--%3E%20C%5B%E5%9F%BA%E7%A1%80%E8%AE%BE%E6%96%BD%E5%85%88%E8%BF%81%5D%0A%20%20C%20--%3E%20D%5B%E6%8C%89%E7%89%B9%E6%80%A7%E7%BA%B5%E5%90%91%E8%BF%81%E7%A7%BB%5D%0A%20%20D%20--%3E%20E%5B%E6%B8%85%E7%90%86%E6%97%A7%E6%A0%88%5D%0A%20%20E%20--%3E%20F%5B%E6%9E%B6%E6%9E%84%E7%BA%A6%E6%9D%9F%E5%9B%BA%E5%8C%96%5D%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[n(" Loading... ",-1)])]),_:1})),t[3]||(t[3]=e('<ul><li><strong>现状盘点</strong>：列出框架版本、路由入口、状态管理、构建方式、测试覆盖与最痛的模块。</li><li><strong>测试与门禁</strong>：没有回归网就不迁移。至少覆盖关键流程与数据契约。</li><li><strong>基础设施先迁</strong>：构建、路由、HTTP、国际化这些横切能力先稳定，业务组件才有共同底座。</li><li><strong>纵向迁移</strong>：按「一个路由 / 一个特性」端到端迁移，而不是按技术层横向切。</li><li><strong>清理旧栈</strong>：删除双写适配层、旧依赖与兼容开关，避免长期维护两套心智。</li><li><strong>约束固化</strong>：把依赖方向、目录职责与升级节奏写进 lint、脚本与文档。</li></ul><h2 id="_2-常见迁移路线与判断标准" tabindex="-1">2. 常见迁移路线与判断标准 <a class="header-anchor" href="#_2-常见迁移路线与判断标准" aria-label="Permalink to &quot;2. 常见迁移路线与判断标准&quot;">​</a></h2><table tabindex="0"><thead><tr><th>迁移项</th><th>机械程度</th><th>主要风险</th><th>判断标准</th></tr></thead><tbody><tr><td>AngularJS → Angular</td><td>低</td><td>双框架共存、DI 与 digest 差异</td><td>按路由灰度，先迁只读页面</td></tr><tr><td>NgModule → standalone</td><td>中高</td><td>共享模块拆分、 provider 作用域变化</td><td>组件能否独立声明依赖、测试是否可独立运行</td></tr><tr><td>构造函数注入 → <code>inject()</code></td><td>高</td><td>继承与初始化顺序</td><td>构造参数是否被用于非 DI 逻辑</td></tr><tr><td><code>*ngIf</code> / <code>*ngFor</code> → 控制流</td><td>高</td><td>模板引用变量、<code>track</code> 语义</td><td>是否有复杂嵌套与动态模板</td></tr><tr><td>手写订阅 → signal / <code>toSignal</code></td><td>中</td><td>双真源、销毁时机</td><td>状态是否只有一个写入方</td></tr><tr><td>Zone.js → zoneless</td><td>中</td><td>依赖 Zone 补丁的第三方库</td><td>是否有库依赖隐式变更检测</td></tr></tbody></table><p>机械程度高不代表零风险：批量改写的代价往往藏在「测试没覆盖到的边界」里。迁移顺序应优先选择 「可观测、可回滚、依赖少」的模块。</p><h2 id="_3-迁移中的三个结构性坑" tabindex="-1">3. 迁移中的三个结构性坑 <a class="header-anchor" href="#_3-迁移中的三个结构性坑" aria-label="Permalink to &quot;3. 迁移中的三个结构性坑&quot;">​</a></h2><p><strong>双真源。</strong> 迁移期常见「signal 与 BehaviorSubject 同时保存同一份状态」。两个写入方会让调试 无从下手。原则是：迁移期间选定一个真源，另一侧只做派生。</p><p><strong>Provider 作用域漂移。</strong> NgModule 的 <code>providers</code> 与组件级 <code>providers</code> 在 standalone 下语义 不同。把服务从模块挪到 <code>app.config.ts</code> 时，要确认它不是「每个特性一份实例」的隐式约定。</p><p><strong>路由双栈。</strong> AngularJS 与 Angular 路由同时接管 URL，会出现刷新后落到错误应用。灰度方案必须 明确「哪些前缀归新应用」，并在反向代理层做兜底。</p><h2 id="_4-架构治理-把依赖方向写死" tabindex="-1">4. 架构治理：把依赖方向写死 <a class="header-anchor" href="#_4-架构治理-把依赖方向写死" aria-label="Permalink to &quot;4. 架构治理：把依赖方向写死&quot;">​</a></h2><p>第 11 章的订单示例已经给出分层：<code>core</code> 提供领域契约与通用能力，<code>features</code> 组织用例，组件只 依赖 Facade，不直接碰请求细节。</p>',10)),(d(),i(s,null,{default:a(()=>[o(r,{id:"mermaid-205",class:"mermaid",graph:"flowchart%20TB%0A%20%20UI%5B%E5%B1%95%E7%A4%BA%E7%BB%84%E4%BB%B6%5D%20--%3E%20F%5BFacade%20%2F%20%E7%94%A8%E4%BE%8B%5D%0A%20%20F%20--%3E%20D%5B%E9%A2%86%E5%9F%9F%E6%A8%A1%E5%9E%8B%5D%0A%20%20F%20--%3E%20R%5B%E4%BB%93%E5%82%A8%E6%8E%A5%E5%8F%A3%5D%0A%20%20R%20--%3E%20I%5B%E5%9F%BA%E7%A1%80%E8%AE%BE%E6%96%BD%E5%AE%9E%E7%8E%B0%5D%0A%20%20D%20-.%E7%A6%81%E6%AD%A2%E5%8F%8D%E5%90%91%E4%BE%9D%E8%B5%96.-%3E%20UI%0A%20%20I%20-.%E7%A6%81%E6%AD%A2%E5%8F%8D%E5%90%91%E4%BE%9D%E8%B5%96.-%3E%20F%0A"})]),fallback:a(()=>[...t[1]||(t[1]=[n(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=e('<p>治理不是多写文档，而是让违规<strong>可失败</strong>：</p><ol><li><strong>目录约定</strong>：<code>core</code> 不允许 import <code>features</code>；<code>features/a</code> 不允许 import <code>features/b</code> 的内部文件。</li><li><strong>边界 lint</strong>：用 ESLint 的 <code>no-restricted-imports</code> 或 Nx 的 module boundaries 固化规则。</li><li><strong>公共出口</strong>：每个特性只暴露 <code>index.ts</code>，内部文件不对外可见。</li><li><strong>所有权</strong>：每个目录有明确的 owner，跨边界修改需要评审。</li><li><strong>ADR</strong>：架构决策记录写清背景、选项、结论与失效条件，避免「口口相传」。</li></ol><p>规则的价值在于「新增代码默认合规」。如果只能靠 review 记忆，边界迟早被绕过。</p><h2 id="_5-版本与弃用治理" tabindex="-1">5. 版本与弃用治理 <a class="header-anchor" href="#_5-版本与弃用治理" aria-label="Permalink to &quot;5. 版本与弃用治理&quot;">​</a></h2><p>Angular 的升级节奏稳定，但每次大版本都会带来弃用项。可持续的做法是把升级变成固定动作，而不是 临时救火：</p><ul><li><strong>固定节奏</strong>：每个大版本一次升级窗口，先升依赖、再清弃用、最后删兼容代码。</li><li><strong>先读弃用清单</strong>：升级前用 <code>ng update</code> 的提示与官方弃用列表建立待办，而不是等编译报错。</li><li><strong>小步提交</strong>：依赖升级与业务改动分开提交，方便定位回归。</li><li><strong>门禁兜底</strong>：类型检查、模板编译、单元测试、构建预算与沙箱新鲜度都要在 CI 中执行。</li></ul><p>本仓库的门禁顺序（<code>check:examples</code> → <code>build:examples</code> → <code>test:examples</code> → <code>docs:build</code>）就是 这个思路的最小版本：先保证示例与文档一致，再保证能构建、能测试、能发布。</p><h2 id="_6-可运行示例" tabindex="-1">6. 可运行示例 <a class="header-anchor" href="#_6-可运行示例" aria-label="Permalink to &quot;6. 可运行示例&quot;">​</a></h2>',8)),o(c,{id:"architecture",height:"560"}),t[5]||(t[5]=e('<h3 id="_6-1-建议先改这里" tabindex="-1">6.1 建议先改这里 <a class="header-anchor" href="#_6-1-建议先改这里" aria-label="Permalink to &quot;6.1 建议先改这里&quot;">​</a></h3><ol><li>在 <code>features/orders</code> 中新增一个 <code>OrdersRepository</code> 的 Fake 实现，并在 <code>app.config.ts</code> 替换 注入。验收：页面行为不变，但不再依赖真实数据源。</li><li>给 <code>OrdersFacade</code> 增加一个 <code>remove(id)</code> 用例，组件只调用 Facade。验收：组件不出现仓储或 HTTP 依赖。</li><li>让 <code>features/orders</code> 尝试 import <code>features/users</code> 的内部文件。验收：你能写出对应的边界规则 （目录级或 lint 级），并说明为什么公共出口应只暴露必要 API。</li><li>把 Facade 中的一份状态改成 <code>computed</code> 派生。验收：写入方仍只有一个，派生值随源状态更新。</li><li>为 <code>OrdersFacade</code> 写一个不依赖网络的测试（Fake 仓储）。验收：测试只装配 Facade 与 Fake， 不需要 TestBed 的 HTTP 模块。</li></ol><h2 id="_7-常见坑" tabindex="-1">7. 常见坑 <a class="header-anchor" href="#_7-常见坑" aria-label="Permalink to &quot;7. 常见坑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>原因</th><th>处理</th></tr></thead><tbody><tr><td>迁移后页面偶发空白</td><td>双路由接管 URL 或懒加载路径错配</td><td>明确前缀归属，检查 <code>base href</code> 与 fallback</td></tr><tr><td>同一状态两处更新</td><td>signal 与 Subject 双真源</td><td>选定唯一写入方，另一侧派生</td></tr><tr><td>服务出现多份实例</td><td>provider 作用域从模块挪到根级</td><td>明确「单例」还是「每特性一份」</td></tr><tr><td>批量改写后测试大面积失败</td><td>机械替换破坏了初始化顺序</td><td>小步提交，先补测试再迁移</td></tr><tr><td>边界规则写了但没人遵守</td><td>只靠文档与 review</td><td>用 lint / 脚本让违规构建失败</td></tr><tr><td>升级后包体积回退</td><td>新依赖进入首屏或未清理旧包</td><td>用构建预算与 stats 产物核对</td></tr><tr><td>旧代码长期保留兼容开关</td><td>迁移没有「清理阶段」</td><td>给兼容层设定删除日期与 owner</td></tr></tbody></table><h2 id="_8-练习" tabindex="-1">8. 练习 <a class="header-anchor" href="#_8-练习" aria-label="Permalink to &quot;8. 练习&quot;">​</a></h2><ol><li>选一个现有特性，画出它的依赖方向图，标出至少一处反向依赖。验收：你能给出具体的拆分或 接口调整方案。</li><li>为一个目录写 3 条 <code>no-restricted-imports</code> 规则。验收：故意违规时 lint 失败，而不是只给警告。</li><li>写一份 ADR：主题是「状态管理选 signal 还是引入第三方库」。验收：包含背景、选项、结论与 重新评估的条件。</li><li>把一次假想的版本升级拆成 4 个提交：依赖、弃用清理、兼容层删除、文档更新。验收：每个提交 都能独立构建与测试。</li><li>给 <code>architecture</code> 示例增加一个「订单归档」用例，并保持组件不直接依赖仓储。验收：Facade 承担编排，组件只读 signal。</li></ol><h2 id="_9-自测" tabindex="-1">9. 自测 <a class="header-anchor" href="#_9-自测" aria-label="Permalink to &quot;9. 自测&quot;">​</a></h2><details><summary><b>1. 为什么迁移要按特性纵向切，而不是按技术层横向切？</b></summary><p>纵向切能把「路由、组件、状态、测试」一次迁完并独立上线，回滚范围小；横向切会让新旧实现长期 并存，同一个页面里同时出现两套模式，风险和心智负担都更高。</p></details><details><summary><b>2. 迁移期为什么要先建立测试与门禁？</b></summary><p>迁移会产生大量机械改动，回归只能靠自动化发现。没有测试与构建门禁，问题会在上线后暴露，修复 成本远高于迁移本身。</p></details><details><summary><b>3. 边界规则怎样才算「有效」？</b></summary><p>能被工具执行、能让违规构建失败，并且新增代码默认满足规则。只写在文档里、依赖 review 记忆的 规则，在人员流动与交付压力下会迅速失效。</p></details><details><summary><b>4. 什么时候应该删除兼容层？</b></summary><p>当旧路径的流量归零、相关测试全部迁移、且没有外部消费者依赖时。删除前应设定明确日期与 owner， 否则兼容层会变成永久技术债。</p></details><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ul><li>迁移应分阶段推进：盘点、门禁、基础设施、纵向迁移、清理、固化约束。</li><li>机械迁移也要小步提交，风险藏在测试未覆盖的边界里。</li><li>双真源、provider 作用域与路由双栈是迁移期最常见的结构性问题。</li><li>架构治理要让依赖方向「可失败」：目录约定、边界 lint、公共出口与所有权。</li><li>版本升级与弃用清理应固定节奏，并由门禁兜底。</li><li>上一章：<a href="/angular-tutorial-site/guide/part7/17-compiler-ivy">17 编译器与 Ivy 运行时</a>；回到：<a href="/angular-tutorial-site/guide/">学习路线</a>。</li></ul>',13))])}const D=E(h,[["render",g]]);export{f as __pageData,D as default};
